using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using OrcaFacil.Application.Abstractions; using OrcaFacil.Domain.Entities; using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Clients; [Authorize] public class IndexModel:PageModel{private readonly OrcaFacilDbContext _db; private readonly ICurrentUserService _current; public List<Client> Clients{get;private set;}=[]; public IndexModel(OrcaFacilDbContext db,ICurrentUserService current){_db=db;_current=current;} public async Task OnGetAsync(CancellationToken ct)=>Clients=await _db.Clients.Where(x=>x.UserId==_current.UserId&&!x.IsDeleted).OrderBy(x=>x.Name).ToListAsync(ct); public static string Mask(Client c)=>BrazilianDocument.Mask(c.DocumentType,c.DocumentNumber);}
